-- Benachrichtigung in der Oberfläche zur Chat-Nachricht (BA10, Stefan 20.10.2026), Art morgen_briefing, gleiche Person wie im Chat.
-- Wirft nie einen Fehler; die Chat-Nachricht läuft unverändert und unabhängig davon (eigener Zweig, läuft vor dem Senden).
SELECT ally_benachrichtigung_aus_chat($1::text, 'morgen_briefing', NULLIF($2::text, ''), 'Morgen-Briefing', NULL, 'ALLY 4') AS r;
